  "ai-chatbot-creation": ["Building an AI Chatbot", "Combining a system prompt, conversation memory and a model API into a useful assistant.", "Like briefing a new assistant on their role and giving them your notes.", "S.M.T.G = System prompt, Memory, Tools, Guardrails", "messages = [{role:'system', content:'You are a maths tutor for beginners.'}, ...history, {role:'user', content: input}]", "What does the system prompt control?", "The assistant's role, tone and boundaries", "The model's training data", "The user's typing speed"],
